package com.citacloud.app.views;
import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.component.textfield.TextArea; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.util.*;
@Route(value="historial-clinico",layout=MainLayout.class) @PageTitle("Historial clínico | CitaCloud") @PermitAll public class HistorialClinicoView extends VerticalLayout {public HistorialClinicoView(HistorialClinicoService historias,PacienteService pacientes){TenantUserDetails u=AuthService.getAuthenticatedUser();UUID empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);add(new H2("Historial clínico"),new Paragraph("Registre resumen, alergias y antecedentes del paciente."));ComboBox<Paciente> paciente=new ComboBox<>("Paciente",empresa==null?List.of():pacientes.listarPorEmpresa(empresa));paciente.setItemLabelGenerator(Paciente::getNombreCompleto);TextArea resumen=new TextArea("Resumen clínico");TextArea alergias=new TextArea("Alergias");TextArea antecedentes=new TextArea("Antecedentes");resumen.setWidthFull();alergias.setWidthFull();antecedentes.setWidthFull();paciente.addValueChangeListener(e->{if(e.getValue()==null)return;historias.listar(empresa).stream().filter(h->h.getPaciente().getId().equals(e.getValue().getId())).findFirst().ifPresent(h->{resumen.setValue(valor(h.getResumen()));alergias.setValue(valor(h.getAlergias()));antecedentes.setValue(valor(h.getAntecedentes()));});});Button guardar=new Button("Guardar historial",e->{try{historias.guardar(empresa,paciente.getValue().getId(),resumen.getValue(),alergias.getValue(),antecedentes.getValue());Notification.show("Historial clínico guardado.");}catch(Exception x){Notification.show(x.getMessage());}});add(paciente,resumen,alergias,antecedentes,guardar);}private String valor(String v){return v==null?"":v;}}
